params.command:
$ErrorActionPreference='Stop'
$repo=Join-Path $env:USERPROFILE 'local-ai-workspaces\mhw-mods'
git -C $repo fetch origin --prune
$base=(git -C $repo rev-parse origin/main).Trim()
$tmp=Join-Path $env:TEMP ('branchzero-updater-'+[guid]::NewGuid().ToString('N'))
git -C $repo worktree add --detach $tmp origin/main | Out-Null
try {
 git -C $tmp cherry-pick b8f9424e274644ff5e76590e7dd44b05fe7c01a6
 if($LASTEXITCODE -ne 0){$conf=@(git -C $tmp diff --name-only --diff-filter=U);[pscustomobject]@{status='conflict';base=$base;conflicts=$conf}|ConvertTo-Json -Compress;exit 21}
 powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $tmp 'scripts\Test-UpdaterDisposable.Tests.ps1')
 if($LASTEXITCODE -ne 0){throw 'UPDATER_HARNESS_TEST_FAILED'}
 git -C $repo fetch origin
 if((git -C $repo rev-parse origin/main).Trim() -ne $base){throw 'MAIN_MOVED'}
 git -C $tmp push origin HEAD:main
 if($LASTEXITCODE -ne 0){throw 'PUSH_MAIN_FAILED'}
 [pscustomobject]@{status='integrated';base=$base;head=(git -C $tmp rev-parse HEAD).Trim()}|ConvertTo-Json -Compress
} finally { git -C $repo worktree remove --force $tmp 2>$null | Out-Null }
